import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSumScores() {
        Assert.assertEquals(155, totalScore(listOf(45, 72, 38)))
    }

    @Test
    fun testSingleScore() {
        Assert.assertEquals(100, totalScore(listOf(100)))
    }

    @Test
    fun testTwoScores() {
        Assert.assertEquals(150, totalScore(listOf(75, 75)))
    }

    @Test
    fun testManyScores() {
        Assert.assertEquals(250, totalScore(listOf(10, 20, 30, 40, 50, 100)))
    }
}
